import unreal
target=None
for obj in unreal.ObjectIterator(unreal.NiagaraScript):
    if obj.get_path_name().endswith(':ProjParticles_0.NiagaraScratchPadContainer_0.SSPR_WriteOccupancy'):
        target=obj
        break
print('TARGET=' + (target.get_path_name() if target else 'None'))
container=target.get_outer() if target else None
print('CONTAINER=' + (container.get_path_name() if container else 'None'))
for key in ('scripts','Scripts'):
    try:
        values=container.get_editor_property(key)
        print('PROP=' + key + '|' + repr([(x.get_name(),x.get_path_name()) for x in values]))
    except Exception as exc: print('ERR=' + key + '|' + str(exc))
